Java.Iterative:
public int match(String text, String pattern) {
    for (int i = 0; i <= text.length() - pattern.length(); i++) {
        int j = 0;
        while (j < pattern.length() && text.charAt(i + j) == pattern.charAt(j)) {
            j++;
        }
        if (j == pattern.length()) {
            return i;
        }
    }
    return -1;
}

Java.Functions:
public int match(String text, String pattern) {
    for (int i = 0; i <= text.length() - pattern.length(); i++) {
        if (compareAt(text, pattern, i)) {
            return i;
        }
    }
    return -1;
}

private boolean compareAt(String text, String pattern, int start) {
    for (int j = 0; j < pattern.length(); j++) {
        if (text.charAt(start + j) != pattern.charAt(j)) {
            return false;
        }
    }
    return true;
}

Java.Recursion:
public int matchRecursive(String text, String pattern, int i) {
    if (i > text.length() - pattern.length()) {
        return -1;
    }
    if (compareRecursive(text, pattern, i, 0)) {
        return i;
    }
    return matchRecursive(text, pattern, i + 1);
}

private boolean compareRecursive(String text, String pattern, int i, int j) {
    if (j == pattern.length()) {
        return true;
    }
    if (text.charAt(i + j) != pattern.charAt(j)) {
        return false;
    }
    return compareRecursive(text, pattern, i, j + 1);
}
